    "source": "import { spawn } from 'node:child_process';
import { promises as fs } from 'node:fs';
import { join } from 'node:path';

export async function gate({ referenceDir, submissionDir }) {
  try {
    // Read the pinned test cases
    const testCasesPath = join(referenceDir, 'pinned-test-cases.txt');
    const testCases = await fs.readFile(testCasesPath, 'utf-8');

    // Read the submission
    const submissionPath = join(submissionDir, 'answer.mjs');
    const submission = await fs.readFile(submissionPath, 'utf-8');

    // Create a test runner that executes the pinned cases against the submission
    const testRunnerCode = `
import assert from 'node:assert/strict';
import { dedupeSorted } from '${submissionPath}';

let passCount = 0;
let failCount = 0;
const results = [];

const test = (name, fn) => {
  try {
    fn();
    passCount++;
    results.push({ name, status: 'pass' });
  } catch (e) {
    failCount++;
    results.push({ name, status: 'fail', error: e.message });
  }
};

${testCases}

console.log(JSON.stringify({ passCount, failCount, results }));
process.exit(failCount > 0 ? 1 : 0);
`;

    // Write the test runner to a temporary file
    const testRunnerPath = join(referenceDir, 'test-runner.mjs');
    await fs.writeFile(testRunnerPath, testRunnerCode);

    // Execute the test runner
    return new Promise((resolve) => {
      const proc = spawn(process.execPath, [testRunnerPath], {
        cwd: referenceDir,
        timeout: 10000
      });

      let stdout = '';
      let stderr = '';

      proc.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      proc.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      proc.on('close', (code) => {
        try {
          const output = JSON.parse(stdout);
          if (code === 0 && output.failCount === 0) {
            resolve({
              accept: true,
              reason: `All ${output.passCount} pinned test cases passed`
            });
          } else {
            const failedTests = output.results
              .filter(r => r.status === 'fail')
              .map(r => `${r.name}: ${r.error}`)
              .join('; ');
            resolve({
              accept: false,
              reason: `${output.failCount} test(s) failed: ${failedTests}`
            });
          }
        } catch (e) {
          resolve({
            accept: false,
            reason: `Test execution failed: ${stderr || stdout || e.message}`
          });
        }
      });

      proc.on('error', (err) => {
        resolve({
          accept: false,
          reason: `Process error: ${err.message}`
        });
      });
    });
  } catch (e) {
    return {
      accept: false,
      reason: `Gate execution error: ${e.message}`
    };
  }
}
"
  },
  "rationale": "Authoring a gate that spawns a Node process to execute the pinned test suite against the submission's dedupeSorted export, capturing and validating all test results before accepting."
}
